export interface TagSettings {
  text: string;
  fontSize: number;
  color: string;
  fontWeight: string;
  opacity: number;
  marginX: number;
  marginY: number;
  usePrefix: boolean;
}

export interface ImageFile {
  id: string;
  file: File;
  previewUrl: string; // Original preview
  processedUrl: string | null; // Preview with watermark
  status: 'pending' | 'processing' | 'done' | 'error';
  width: number;
  height: number;
}

import { TagSettings } from '../types';

/**
 * Loads an image from a URL or File
 */
export const loadImage = (url: string): Promise<HTMLImageElement> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = (err) => reject(err);
    img.src = url;
  });
};

/**
 * Processes a single image file with the given settings
 */
export const processImageWithWatermark = async (
  imageElement: HTMLImageElement,
  settings: TagSettings
): Promise<string> => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  if (!ctx) throw new Error('Canvas context not found');

  // Set canvas size to original image size
  canvas.width = imageElement.width;
  canvas.height = imageElement.height;

  // Draw original image
  ctx.drawImage(imageElement, 0, 0);

  // Configure text style
  // Use Noto Sans SC which we imported in index.html
  ctx.font = `${settings.fontWeight} ${settings.fontSize}px 'Noto Sans SC'`;
  ctx.fillStyle = settings.color;
  ctx.globalAlpha = settings.opacity;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'bottom';

  // Apply drop shadow for better readability on varied backgrounds
  ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
  ctx.shadowBlur = 4;
  ctx.shadowOffsetX = 2;
  ctx.shadowOffsetY = 2;

  // Position: Bottom Left
  // Margin from bottom-left corner
  const x = settings.marginX;
  const y = canvas.height - settings.marginY;

  ctx.fillText(settings.text, x, y);

  return canvas.toDataURL('image/jpeg', 0.95);
};

/**
 * Downloads a base64 or blob URL
 */
export const downloadUrl = (url: string, filename: string) => {
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

